Days": [0, 6], "adjustment": "next_business_day"}, "allocation": ["fine", "lateInterest", "interest", "principal"], "excess": "advance", "settlement": "due_interest", "yearDays": 365, "requirements": {"documents": ["BI"], "guarantees": [], "minAge": null, "minIncome": null}, "approvalLevels": [{"upTo": "10000000", "role": "manager"}]}}, {"key": "business", "name": "Crédito PME", "terms": {"method": "annuity", "periodicity": "monthly", "rate": "0.04", "minPrincipal": "100000", "maxPrincipal": "50000000", "minPeriods": 6, "maxPeriods": 36, "grace": {"periods": 0, "treatment": "free"}, "fees": [], "taxes": [], "penalty": {"toleranceDays": 3, "dailyRate": "0", "fine": {"kind": "fixed", "value": "0"}}, "calendar": {"holidays": [], "weekendDays": [0, 6], "adjustment": "next_business_day"}, "allocation": ["fine", "lateInterest", "interest", "principal"], "excess": "advance", "settlement": "due_interest", "yearDays": 365, "requirements": {"documents": ["BI"], "guarantees": ["Garantia"], "minAge": null, "minIncome": null}, "approvalLevels": [{"upTo": "50000000", "role": "manager"}]}}]$preset$::jsonb);

-- Upgrade only initial draft configurations; they have never been published.
do $$declare c record; preset jsonb; p uuid;begin
 for c in select * from public.tenant_configuration where category='product' loop
 select value into preset from jsonb_array_elements((select configuration->'products' from public.presets where id='20000000-0000-4000-8000-000000000001')) where value->>'key'=c.key;
 if preset is not null then
 insert into public.products(tenant_id,name,source_key,revision) values(c.tenant_id,c.value->>'name',c.key,1) returning id into p;
 insert into public.product_versions(product_id,tenant_id,version,name,terms) values(p,c.tenant_id,1,c.value->>'name',preset->'terms');
 end if;end loop;
end;$$;
-- New tenant presets materialise real draft products in the same transaction.
create function public.initial_product() returns trigger language plpgsql security definer set search_path='' as $$
declare p uuid;begin
 if new.category='product' and new.value ? 'terms' then
 insert into public.products(tenant_id,name,source_key,revision) values(new.tenant_id,new.value->>'name',new.key,1) returning id into p;
 insert into public.product_versions(product_id,tenant_id,version,name,terms,created_by) values(p,new.tenant_id,1,new.value->>'name',new.value->'terms',auth.uid());
 end if;return new;
end;$$;
revoke all on function public.initial_product() from public,anon,authenticated;
create trigger initialise_product after insert on public.tenant_configuration for each row execute function public.initial_product();
